<?php require __DIR__.'/config.php';$u=require_login();$b=require_business();$id=(int)$_GET['id'];$s=db()->prepare("SELECT q.*,l.name location_name FROM qr_codes q LEFT JOIN locations l ON l.id=q.location_id WHERE q.id=? AND q.business_id=?");$s->execute([$id,$b['id']]);$q=$s->fetch();if(!$q)exit('Not found');$url=base_url().'/q.php?t='.$q['token'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>QR · SERV</title><link rel="stylesheet" href="assets/css/app.css"></head><body><main class="print-card"><div class="brand">SERV</div><div class="eyebrow"><?=e($b['name'])?></div><h1><?=e($q['label'])?></h1><p>Scan to order or request service</p><div class="qr"><img src="qr-image.php?d=<?=rawurlencode($url)?>" alt="SERV QR"></div><p class="small"><?=e($url)?></p><button class="btn gold" onclick="print()">Print QR</button></main></body></html>
